INSERT INTO timeslot (center_id, start_time, end_time, capacity)
SELECT 
    center_id,
    DATE_ADD(start_time, INTERVAL 1 WEEK),
    DATE_ADD(end_time, INTERVAL 1 WEEK),
    capacity
FROM timeslot
WHERE start_time >= '2024-03-25' AND start_time < '2024-04-01'; 